{"file_text": ".application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    margin-bottom: 0.4rem;
    transition: all 0.2s;
}

.step.active .step-circle {
    background-color: #4361ee;
    color: white;
    box-shadow: 0 0 0 4px rgba(67, 97, 238, 0.2);
}

.step.completed .step-circle {
    background-color: #2ecc71;
    color: white;
}

.step.future .step-circle {
    background-color: #e0e0e0;
    color: #999;
}

.step-label {
    font-size: 0.7rem;
    text-align: center;
    color: #666;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step.future .step-label {
    color: #999;
}

.step-connector {
    flex: 1;
    height: 2px;
    background-color: #e0e0e0;
    margin: 0 0.3rem;
    margin-bottom: 1.2rem;
    min-width: 20px;
    max-width: 60px;
}

.step-connector.completed {
    background-color: #2ecc71;
}

/* Form Sections */
.form-section {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

.form-section h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
    border-bottom: 2px solid #f0f0f0;
    padding-bottom: 0.5rem;
}

.form-group {
    margin-bottom: 1.2rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.7rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.checkbox-group input[type="checkbox"] {
    width: auto;
}

.checkbox-group label {
    display: inline;
    margin-bottom: 0;
}

/* Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h3 {
    margin: 0;
    color: #444;
}

/* Buttons */
.form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #f0f0f0;
}

.btn-next,
.btn-back,
.btn-submit,
.btn-add,
.btn-remove,
.btn-edit {
    padding: 0.7rem 1.5rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-next {
    background-color: #4361ee;
    color: white;
    margin-left: auto;
}

.btn-next:hover:not(:disabled) {
    background-color: #3451d1;
}

.btn-next:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-back {
    background-color: #f0f0f0;
    color: #333;
}

.btn-back:hover {
    background-color: #e0e0e0;
}

.btn-submit {
    background-color: #2ecc71;
    color: white;
    padding: 0.8rem 2rem;
    font-size: 1rem;
}

.btn-submit:hover:not(:disabled) {
    background-color: #27ae60;
}

.btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-add {
    background-color: transparent;
    color: #4361ee;
    border: 1px dashed #4361ee;
    width: 100%;
    margin-bottom: 1rem;
    padding: 0.8rem;
}

.btn-add:hover {
    background-color: rgba(67, 97, 238, 0.05);
}

.btn-remove {
    background-color: transparent;
    color: #e74c3c;
    border: 1px solid #e74c3c;
    padding: 0.4rem 0.8rem;
    font-size: 0.8rem;
}

.btn-remove:hover {
    background-color: rgba(231, 76, 60, 0.05);
}

.btn-edit {
    background-color: transparent;
    color: #4361ee;
    border: 1px solid #4361ee;
    padding: 0.3rem 0.8rem;
    font-size: 0.8rem;
}

.btn-edit:hover {
    background-color: rgba(67, 97, 238, 0.05);
}

/* Cover Letter */
.cover-letter-input {
    min-height: 200px !important;
}

.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.3rem;
}

/* Error Message */
.error-message {
    background-color: #fdeaea;
    color: #c0392b;
    padding: 0.8rem 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
    border-left: 4px solid #e74c3c;
}

/* Review Section */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.2rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.8rem;
}

.review-header h3 {
    margin: 0;
    color: #1a1a2e;
    font-size: 1rem;
}

.review-content p {
    margin: 0.3rem 0;
    font-size: 0.9rem;
    color: #555;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.review-description {
    font-style: italic;
    color: #777 !important;
}

.review-cover-letter {
    white-space: pre-wrap;
    line-height: 1.5;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
}

.confirmation-icon {
    width: 64px;
    height: 64px;
    background-color: #2ecc71;
    color: white;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    margin: 0 auto 1rem;
}

.confirmation h2 {
    border-bottom: none;
    color: #2ecc71;
}

.application-id {
    font-size: 1.1rem;
    margin-top: 1rem;
}
